'use strict';
const $=id=>document.getElementById(id), KEY='gridline.offline.events.v2', LEGACY='gridline.offline.events.v1';
const colors={F1:'#339cff',MotoGP:'#55ccff',WEC:'#897dff',WRC:'#58bcaa',IndyCar:'#aaaaff','Formula E':'#00d8ed',NASCAR:'#ec96c9'};
let lang='en',storageOK=true,events=[],edit=null,filter='all',query='',view='calendar',month=new Date(new Date().getFullYear(),new Date().getMonth(),1);
try{lang=localStorage.getItem('gridline.language')||'en'}catch{}if(!DICT[lang])lang='en';
const t=k=>DICT[lang][k], esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDay=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const dateOf=e=>e.all_day?new Date(e.start_utc.slice(0,10)+'T12:00:00'):new Date(e.start_utc);
const fmt=(d,o)=>new Intl.DateTimeFormat(lang,{...o,timeZone:prefs.timezone||undefined}).format(d);
function validate(e){if(!e||!Number.isSafeInteger(e.id)||e.id<1||!Object.hasOwn(colors,e.series)||!['scheduled','completed','cancelled'].includes(e.status))throw Error(t('invalid'));for(const k of ['title','venue','country'])if(typeof e[k]!=='string'||!e[k].trim()||e[k].length>150)throw Error(t('invalid'));if(typeof e.description!=='string'||e.description.length>1000||!Number.isFinite(Date.parse(e.start_utc))||!Number.isFinite(Date.parse(e.end_utc))||e.end_utc<=e.start_utc)throw Error(t('invalid'));if(e.all_day!==undefined&&typeof e.all_day!=='boolean')throw Error(t('invalid'));}
function validateRows(rows){if(!Array.isArray(rows)||rows.length>5000)throw Error(t('invalid'));const ids=new Set();for(const e of rows){validate(e);if(ids.has(e.id))throw Error(t('invalid'));ids.add(e.id)}}
async function persist(rows){await api('/api/replace',{events:rows});events=rows;storageOK=true}
async function initialize(){try{events=(await api('/api/events')).events;storageOK=true;translate()}catch(e){storageOK=false;translate();toast(e.message)}}
function translate(){document.documentElement.lang=lang;$('language').value=lang;document.querySelectorAll('[data-t]').forEach(el=>el.textContent=t(el.dataset.t));$('search').placeholder=t('search');$('search').setAttribute('aria-label',t('search'));$('prevMonth').textContent='‹';$('nextMonth').textContent='›';$('prevMonth').setAttribute('aria-label',t('previous'));$('nextMonth').setAttribute('aria-label',t('nextMonth'));$('dialogTitle').textContent=t(edit===null?'new':'edit');render()}
function render(){renderStandings();events.sort((a,b)=>a.start_utc.localeCompare(b.start_utc));const rows=visibleRows();const today=localDay(new Date());const future=rows.filter(e=>e.status==='scheduled'&&(e.all_day?e.end_utc.slice(0,10)>=today:Date.parse(e.end_utc)>Date.now()));$('total').textContent=rows.length;$('upcoming').textContent=future.length;$('activeSeries').textContent=new Set(rows.map(e=>e.series)).size;$('nextEvent').textContent=future[0]?.title||t('none');$('storageStatus').textContent=t(storageOK?'storage':'storageError');
$('seriesFilters').innerHTML=['all',...Object.keys(colors)].map(s=>`<button class="series-option ${filter===s?'active':''}" data-filter="${esc(s)}"><span class="series-dot" style="background:${colors[s]||'#339cff'}"></span>${s==='all'?t('all'):s}</button>`).join('');document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;render()});
$('monthTitle').textContent=fmt(month,{year:'numeric',month:'long'});$('weekdays').innerHTML=Array.from({length:7},(_,i)=>`<span>${fmt(new Date(2026,0,5+i),{weekday:'short'})}</span>`).join('');
const y=month.getFullYear(),m=month.getMonth(),offset=(month.getDay()+6)%7,count=Math.ceil((offset+new Date(y,m+1,0).getDate())/7)*7;let html='';for(let i=0;i<count;i++){const d=new Date(y,m,1-offset+i),day=localDay(d);const matches=rows.filter(e=>e.all_day?e.start_utc.slice(0,10)<=day&&e.end_utc.slice(0,10)>=day:startDay(e)===day);html+=`<div class="day ${d.getMonth()!==m?'muted':''} ${day===today?'today':''}"><span class="num">${d.getDate()}</span>${matches.map(e=>`<button class="event-chip ${e.status}" data-event="${e.id}" style="--accent:${colors[e.series]}" title="${esc(e.title)}">${esc(e.series)} · ${esc(e.title)}</button>`).join('')}</div>`}$('calendarGrid').innerHTML=html;
const first=localDay(month),last=localDay(new Date(y,m+1,0));const listed=rows.filter(e=>e.all_day?e.start_utc.slice(0,10)<=last&&e.end_utc.slice(0,10)>=first:startDay(e)>=first&&startDay(e)<=last);$('eventList').innerHTML=listed.length?listed.map(e=>`<button class="list-item" data-event="${e.id}"><span class="list-date">${fmt(dateOf(e),{day:'2-digit'})}<small>${fmt(dateOf(e),{month:'short'})}</small></span><span class="info"><span class="pill" style="--accent:${colors[e.series]}">${esc(e.series)}</span><strong>${esc(e.title)}</strong><small>${esc(e.venue)} · ${esc(e.country)} · ${e.all_day?t('dateOnly'):fmt(dateOf(e),{hour:'2-digit',minute:'2-digit'})}</small><br><span class="status">${t(e.status)}</span></span><span>›</span></button>`).join(''):`<p class="subtitle">${t('empty')}</p>`;
document.querySelectorAll('[data-event]').forEach(el=>el.onclick=()=>openEvent(Number(el.dataset.event)));$('calendarView').hidden=view!=='calendar';$('listView').hidden=view!=='list';$('navCalendar').classList.toggle('active',view==='calendar');$('navList').classList.toggle('active',view==='list');renderFeatures();}
const form=$('eventForm'),dialog=$('eventDialog');
const localInput=iso=>{const d=new Date(iso);return new Date(+d-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
function dateTypes(){const all=form.elements.all_day.checked;for(const k of ['start_utc','end_utc']){const el=form.elements[k],v=el.value;el.type=all?'date':'datetime-local';el.value=all?v.slice(0,10):v.length===10?v+'T12:00':v}}
function openEvent(id=null){edit=id;form.reset();const e=events.find(e=>e.id===id);$('dialogTitle').textContent=t(e?'edit':'new');$('deleteBtn').hidden=!e;$('formError').textContent='';form.elements.all_day.checked=e?!!e.all_day:true;dateTypes();if(e){for(const k of ['title','series','status','venue','country','description'])form.elements[k].value=e[k];for(const k of ['start_utc','end_utc'])form.elements[k].value=e.all_day?e[k].slice(0,10):localInput(e[k])}else{form.elements.start_utc.value=localDay(new Date());form.elements.end_utc.value=localDay(new Date())}for(const k of ['session_type','drivers','teams','watch_url','ticket_url','lat','lon','result'])form.elements[k].value=e?.[k]??(k==='session_type'?'weekend':'');form.elements.result.closest('label').hidden=prefs.spoiler;$('sourceLine').textContent='';if(e?.source&&/^https:\/\//.test(e.source)){const a=document.createElement('a');a.href=e.source;a.target='_blank';a.rel='noopener noreferrer';a.className='source';a.textContent=t('source')+' · '+(e.source_date||'');$('sourceLine').append(a)}dialog.showModal()}
form.elements.all_day.onchange=dateTypes;
form.onsubmit=async ev=>{ev.preventDefault();try{const all=form.elements.all_day.checked,existing=events.find(e=>e.id===edit),data={...existing,id:edit??Math.max(0,...events.map(e=>e.id))+1,all_day:all,is_demo:0};for(const k of ['title','series','status','venue','country','description'])data[k]=form.elements[k].value.trim();data.start_utc=all?form.elements.start_utc.value+'T00:00:00.000Z':new Date(form.elements.start_utc.value).toISOString();data.end_utc=all?form.elements.end_utc.value+'T23:59:59.000Z':new Date(form.elements.end_utc.value).toISOString();for(const k of ['session_type','drivers','teams','watch_url','ticket_url','lat','lon','result'])data[k]=form.elements[k].value;validate(data);if(existing){delete data.source;delete data.source_date;delete data.source_id}await persist(edit===null?[...events,data]:events.map(e=>e.id===edit?data:e));dialog.close();render()}catch(e){$('formError').textContent=e.message}};
$('deleteBtn').onclick=async()=>{if(edit===null||!confirm(t('deleteConfirm')))return;try{await persist(events.filter(e=>e.id!==edit));dialog.close();render()}catch(e){$('formError').textContent=e.message}};
function download(content,name,type){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([content],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
$('backupBtn').onclick=()=>download(JSON.stringify({version:2,events},null,2),'GRIDLINE-backup.json','application/json');$('restoreBtn').onclick=()=>$('restoreInput').click();$('restoreInput').onchange=async ev=>{try{const file=ev.target.files[0];if(!file)return;if(file.size>5000000)throw Error(t('invalid'));const data=JSON.parse(await file.text());if(![1,2].includes(data.version))throw Error(t('invalid'));validateRows(data.events);if(!confirm(t('restoreConfirm')))return;await persist(data.events);render()}catch(e){alert(e.message)}finally{ev.target.value=''}};
function makeICS(){const dt=s=>s.replace(/[-:]/g,'').replace(/\.\d{3}/,'');const escapeICS=s=>String(s).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//GRIDLINE Offline//EN','CALSCALE:GREGORIAN'];events.filter(e=>e.status!=='cancelled').forEach(e=>{lines.push('BEGIN:VEVENT','UID:'+e.id+'@gridline.offline','DTSTAMP:'+dt(new Date().toISOString()));if(e.all_day){const end=new Date(e.end_utc.slice(0,10)+'T00:00:00Z');end.setUTCDate(end.getUTCDate()+1);lines.push('DTSTART;VALUE=DATE:'+e.start_utc.slice(0,10).replace(/-/g,''),'DTEND;VALUE=DATE:'+end.toISOString().slice(0,10).replace(/-/g,''))}else lines.push('DTSTART:'+dt(e.start_utc),'DTEND:'+dt(e.end_utc));lines.push('SUMMARY:'+escapeICS(e.series+' - '+e.title),'LOCATION:'+escapeICS(e.venue+', '+e.country),'DESCRIPTION:'+escapeICS(e.description));if(e.source)lines.push('URL:'+e.source);lines.push('END:VEVENT')});lines.push('END:VCALENDAR','');return lines.map(line=>{let result='',bytes=0;for(const c of line){const n=new TextEncoder().encode(c).length;if(bytes+n>75){result+='\r\n ';bytes=1}result+=c;bytes+=n}return result}).join('\r\n')}
$('exportBtn').onclick=()=>download(makeICS(),'GRIDLINE.ics','text/calendar;charset=utf-8');
$('newBtn').onclick=()=>openEvent();$('closeDialog').onclick=$('cancelBtn').onclick=()=>dialog.close();$('prevMonth').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1);render()};$('nextMonth').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1);render()};$('todayBtn').onclick=()=>{month=new Date(new Date().getFullYear(),new Date().getMonth(),1);render()};$('navCalendar').onclick=()=>{view='calendar';render()};$('navList').onclick=()=>{view='list';render()};$('search').oninput=e=>{query=e.target.value;render()};$('language').onchange=e=>{lang=e.target.value;try{localStorage.setItem('gridline.language',lang)}catch{}translate()};$('seriesSelect').innerHTML=Object.keys(colors).map(s=>`<option>${s}</option>`).join('');function standingsTable(rows,label){return `<div class="table-scroll"><table><caption>${esc(label)}</caption><thead><tr><th scope="col">#</th><th scope="col">${t('competitor')}</th><th scope="col">${t('points')}</th><th scope="col">${t('gap')}</th></tr></thead><tbody>${rows.map(([name,pts],i)=>`<tr><td>${i+1}</td><th scope="row">${esc(name)}</th><td class="points">${new Intl.NumberFormat(lang).format(pts)}</td><td>${i===0?'—':new Intl.NumberFormat(lang).format(rows[0][1]-pts)}</td></tr>`).join('')}</tbody></table></div>`}
function renderStandings(){if(prefs.spoiler){$('standingsContent').innerHTML='<p class=offline-note>'+x('spoilerHidden')+'</p>';return}const selected=filter==='all'?Object.keys(STANDINGS):(STANDINGS[filter]?[filter]:[]);$('standingsContent').innerHTML=selected.map(series=>{const d=STANDINGS[series];return `<article class="standings-card"><div class="standings-head"><div><span class="eyebrow">${esc(d.season)}</span><h2 style="color:${colors[series]}">${esc(series)}</h2></div><a class="source" href="${esc(d.source)}" target="_blank" rel="noopener noreferrer">${t('dataSource')} ↗</a></div><p class="subtitle">${t('topTen')} · ${t(d.type)}</p>${standingsTable(d.rows,t(d.type))}${d.manufacturers?standingsTable(d.manufacturers,t('manufacturers')):''}${d.official?`<p><a class="source" href="${esc(d.official)}" target="_blank" rel="noopener noreferrer">${t('source')} ↗</a></p>`:''}</article>`}).join('');$('standingsView').hidden=view!=='standings';$('navStandings').classList.toggle('active',view==='standings');$('calendarToolbar').hidden=view==='standings';$('newBtn').hidden=view==='standings';}
$('navStandings').onclick=()=>{view='standings';render()};

