const defaults={series:[],drivers:[],teams:[],events:[],visited:[],plan:[],spoiler:false,timezone:'',reminder:15,favoritesOnly:false,racesOnly:false,notifications:false};let prefs={...defaults};try{const saved=JSON.parse(localStorage.getItem('gridline.profile')||'{}');prefs={...defaults,...saved};for(const k of ['series','drivers','teams','events','visited','plan'])if(!Array.isArray(prefs[k]))prefs[k]=[];if(prefs.timezone)new Intl.DateTimeFormat('en',{timeZone:prefs.timezone})}catch{prefs={...defaults}}let client;try{client=localStorage.getItem('gridline.client')||crypto.randomUUID();localStorage.setItem('gridline.client',client)}catch{client=crypto.randomUUID()}
let page='home',focusDate=localDay(new Date()),mode='month',requests=[],statusData=null;let planFrom='08:00',planTo='23:00';
async function api(url,data){const r=await fetch(url,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{});const result=await r.json();if(!r.ok)throw Error(result.error||'Request failed');return result}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,6000)}
function savePrefs(){try{localStorage.setItem('gridline.profile',JSON.stringify(prefs))}catch{toast(t('saveError'))}}
function toggle(kind,value){const list=prefs[kind];prefs[kind]=list.includes(value)?list.filter(x=>x!==value):[...list,value];savePrefs();render()}
function isFavorite(e){return prefs.series.includes(e.series)||prefs.events.includes(e.id)||prefs.drivers.some(n=>(e.drivers||'').toLowerCase().includes(n.toLowerCase()))||prefs.teams.some(n=>(e.teams||'').toLowerCase().includes(n.toLowerCase()))}
function dayInZone(iso){return new Intl.DateTimeFormat('en-CA',{timeZone:prefs.timezone||undefined,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(iso))}
function startDay(e){return e.all_day?e.start_utc.slice(0,10):dayInZone(e.start_utc)}
function endDay(e){return e.all_day?e.end_utc.slice(0,10):dayInZone(e.end_utc)}
function plusDay(day,n){const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
function weekendRange(day){const d=new Date(day+'T12:00:00Z'),dow=d.getUTCDay();const friday=plusDay(day,dow===0?-2:dow===6?-1:5-dow);return [friday,plusDay(friday,2)]}
function visibleRows(){return events.filter(e=>(filter==='all'||e.series===filter)&&(!prefs.favoritesOnly||isFavorite(e))&&(!prefs.racesOnly||['race','sprint','stage'].includes(e.session_type))&&[e.title,e.venue,e.country,e.drivers,e.teams].join(' ').toLocaleLowerCase(lang).includes(query.toLocaleLowerCase(lang)))}
function inRange(rows,a,b){return rows.filter(e=>startDay(e)<=b&&endDay(e)>=a).sort((a,b)=>a.start_utc.localeCompare(b.start_utc))}
function overlap(rows){const r=rows.filter(e=>!e.all_day&&['scheduled','completed'].includes(e.status)).sort((a,b)=>a.start_utc.localeCompare(b.start_utc));let pairs=[];for(let i=0;i<r.length;i++)for(let j=i+1;j<r.length&&r[j].start_utc<r[i].end_utc;j++)pairs.push([r[i],r[j]]);return pairs}
function countdown(e){if(e.all_day)return x('dateOnly');const ms=Date.parse(e.start_utc)-Date.now();if(e.status!=='scheduled')return e.status;if(ms<0)return Date.parse(e.end_utc)>Date.now()?x('plannedNow'):t('completed');const min=Math.ceil(ms/60000);return `${Math.floor(min/1440)}d ${Math.floor(min%1440/60)}h ${min%60}m`}
function link(url,label){return /^https:\/\//.test(url||'')?`<a class="source" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:''}
function eventCard(e){return `<article class="race-card"><div><span class="pill" style="--accent:${colors[e.series]}">${esc(e.series)} · ${esc(e.session_type||'weekend')}</span><h3><button class="text-button" data-edit="${e.id}">${esc(e.title)}</button></h3><p>${esc(e.venue)} · ${e.all_day?esc(startDay(e)+' → '+endDay(e)):esc(fmt(new Date(e.start_utc),{weekday:'short',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}))}</p><p class="countdown" data-countdown="${e.id}">${esc(countdown(e))}</p></div><div class="card-actions"><button class="secondary" data-star="${e.id}" aria-label="${x('favorites')}">${prefs.events.includes(e.id)?'★':'☆'}</button><button class="secondary" data-plan="${e.id}">${prefs.plan.includes(e.id)?x('remove'):x('add')}</button>${link(e.watch_url,x('watch'))}${link(e.source,x('source'))}</div></article>`}
function cards(rows){return rows.length?rows.map(eventCard).join(''):`<p class="subtitle">${x('noEvents')}</p>`}
function controls(){return `<div class="feature-controls"><label>${x('day')}<input type="date" id="featureDate" value="${focusDate}"></label><label><input type="checkbox" id="favoritesOnly" ${prefs.favoritesOnly?'checked':''}>${x('filterFavorites')}</label><label><input type="checkbox" id="racesOnly" ${prefs.racesOnly?'checked':''}>${x('racesOnly')}</label></div>`}
function conflictPanel(rows){const pairs=overlap(rows);return `<details class="offline-note" ${pairs.length?'open':''}><summary>${x('conflicts')}: ${pairs.length}</summary>${pairs.length?pairs.map(([a,b])=>`<p>${esc(a.series+' · '+a.title)} ↔ ${esc(b.series+' · '+b.title)}</p>`).join(''):x('noConflicts')}</details>`}
function renderFeatures(){document.querySelectorAll('[data-x]').forEach(el=>el.textContent=x(el.dataset.x));$('search').placeholder=x('searchHint');$('storageStatus').textContent=storageOK?x('serverNote'):t('storageError');const feature=!['calendar','list','standings'].includes(view);$('featureView').hidden=!feature;$('calendarToolbar').hidden=feature||view==='standings';$('standingsView').hidden=view!=='standings';$('newBtn').hidden=view==='standings';document.querySelectorAll('[data-page]').forEach(el=>el.classList.toggle('active',view===el.dataset.page));document.querySelector('.weekdays').hidden=mode!=='month';$('calendarGrid').hidden=mode!=='month';let agenda=$('calendarAgenda');if(!agenda){agenda=document.createElement('div');agenda.id='calendarAgenda';$('calendarView').append(agenda)}agenda.hidden=mode==='month';if(view==='calendar'&&mode!=='month'){const dow=new Date(focusDate+'T12:00:00Z').getUTCDay(),a=mode==='day'?focusDate:plusDay(focusDate,-((dow+6)%7)),b=mode==='day'?a:plusDay(a,6);agenda.innerHTML=`<h2>${a} → ${b}</h2>`+cards(inRange(visibleRows(),a,b))+conflictPanel(inRange(visibleRows(),a,b))}
if(feature){const rows=visibleRows(),today=dayInZone(new Date().toISOString()),tomorrow=plusDay(today,1);let h=`<h2>${x(view)}</h2>`;
if(view==='home'){h+=controls()+`<div class="feature-grid"><section><h3>${x('today')}</h3>${cards(inRange(rows,today,today))}</section><section><h3>${x('tomorrow')}</h3>${cards(inRange(rows,tomorrow,tomorrow))}</section></div><h3>${x('soon')}</h3>`+cards(rows.filter(e=>e.status==='scheduled'&&startDay(e)>tomorrow).slice(0,5));}
if(view==='weekend'){const [a,b]=weekendRange(focusDate),r=inRange(rows,a,b);h+=controls()+`<p class="subtitle">${a} → ${b} · ${r.length} ${t('total').toLowerCase()}</p>`+conflictPanel(r);for(let day=a;day<=b;day=plusDay(day,1))h+=`<h3>${day}</h3>`+cards(inRange(r,day,day));}
if(view==='planner'){const [a,b]=weekendRange(focusDate);h+=controls()+`<div class="feature-controls"><label>${x('availableFrom')}<input id="planFrom" type="time" value="${planFrom}"></label><label>${x('availableTo')}<input id="planTo" type="time" value="${planTo}"></label><button class="primary" id="buildPlan">${x('plan')}</button><button class="secondary" id="exportPlan">${x('exportPlan')}</button></div><p class="subtitle">${x('dateOnly')} · ${a} → ${b}</p>`+conflictPanel(events.filter(e=>prefs.plan.includes(e.id)))+cards(events.filter(e=>prefs.plan.includes(e.id)));}
if(view==='following'){h+=`<h3>${t('series')}</h3><div class="chips">`+Object.keys(colors).map(s=>`<button class="secondary ${prefs.series.includes(s)?'chosen':''}" data-follow-series="${esc(s)}">${prefs.series.includes(s)?'★':'☆'} ${esc(s)}</button>`).join('')+'</div>';for(const kind of ['drivers','teams'])h+=`<h3>${x(kind)}</h3><form data-follow-form="${kind}"><input name="name" required maxlength="150" placeholder="${x(kind)}"><button class="secondary">${x('follow')}</button></form><div class="chips">${prefs[kind].map(n=>`<button class="secondary" data-follow-name="${esc(n)}" data-kind="${kind}">${esc(n)} ×</button>`).join('')}</div>`;h+=`<h3>${x('favorites')}</h3>`+cards(events.filter(isFavorite));}
if(view==='circuits'){const venues=[...new Set(events.map(e=>e.venue))];h+=venues.map(v=>{const r=events.filter(e=>e.venue===v),e=r.find(e=>e.lat!==undefined&&e.lon!==undefined)||r[0];return `<article class="standings-card"><h3>${esc(v)} · ${esc(e.country)}</h3><button class="secondary" data-visited="${esc(v)}">${prefs.visited.includes(v)?'✓ ':''}${x('visited')}</button> ${link('https://www.openstreetmap.org/search?query='+encodeURIComponent(v+' '+e.country),'Map')} ${link(e.ticket_url,x('tickets'))}<p>${r.length} ${t('total').toLowerCase()}</p>${e.lat!==undefined&&e.lon!==undefined?`<button class="secondary" data-weather="${e.id}">${x('weather')}</button><div id="weather-${e.id}"></div>`:`<p class="subtitle">${x('noWeather')}</p>`}${cards(r)}</article>`}).join('');}
if(view==='results')h+=prefs.spoiler?`<p class="offline-note">${x('spoilerHidden')}</p>`:events.some(e=>e.result)?events.filter(e=>e.result).map(e=>`<article class="standings-card"><h3>${esc(e.series+' · '+e.title)}</h3><p class="result-text">${esc(e.result)}</p>${link(e.source,x('source'))}</article>`).join(''):`<p class="offline-note">${x('noResults')}</p>`;
if(view==='settings'){h+=`<div class="standings-card"><label>${x('timezone')}<select id="timezone"><option value="">${x('localTime')}</option>${Intl.supportedValuesOf('timeZone').map(z=>`<option ${prefs.timezone===z?'selected':''}>${z}</option>`).join('')}</select></label><label><input type="checkbox" id="spoiler" ${prefs.spoiler?'checked':''}>${x('spoiler')}</label><label>${x('reminder')}<select id="reminder">${[5,15,30,60].map(n=>`<option ${prefs.reminder===n?'selected':''}>${n}</option>`).join('')}</select></label><button class="secondary" id="enableNotifications">${x('notifications')}</button><p>${x('notificationNote')}</p></div><div class="standings-card"><h3>${x('feed')}</h3><p>${x('coverageNote')}</p><p>${x('feedNote')}</p><p id="feedStatus">${esc(statusData?.lastImport?JSON.stringify(statusData.lastImport):'—')}</p><button class="secondary" id="refreshData">${x('refresh')}</button><label>${x('import')}<input type="file" id="scheduleImport" accept=".json,application/json"></label><label>Calendar subscription URL<input readonly value="${esc(location.origin+'/api/calendar.ics')}"></label><p class="subtitle">Google / Apple / Outlook: import .ics, or subscribe to this URL from a device that can reach this server.</p></div><div class="standings-card"><h3>${x('requests')}</h3><form id="requestForm"><input name="name" required maxlength="100"><button class="secondary">${x('request')}</button></form>${requests.map(r=>`<p>${esc(r.name)} · ${r.votes} <button class="secondary" data-vote="${r.id}">${x('vote')}</button></p>`).join('')}</div>`}
$('featureView').innerHTML=h;}
bindFeatures();}
function bindFeatures(){document.querySelectorAll('[data-edit]').forEach(el=>el.onclick=()=>openEvent(Number(el.dataset.edit)));document.querySelectorAll('[data-star]').forEach(el=>el.onclick=()=>toggle('events',Number(el.dataset.star)));document.querySelectorAll('[data-plan]').forEach(el=>el.onclick=()=>toggle('plan',Number(el.dataset.plan)));document.querySelectorAll('[data-follow-series]').forEach(el=>el.onclick=()=>toggle('series',el.dataset.followSeries));document.querySelectorAll('[data-follow-name]').forEach(el=>el.onclick=()=>toggle(el.dataset.kind,el.dataset.followName));document.querySelectorAll('[data-follow-form]').forEach(el=>el.onsubmit=e=>{e.preventDefault();const n=el.elements.name.value.trim();if(n&&!prefs[el.dataset.followForm].includes(n))toggle(el.dataset.followForm,n)});document.querySelectorAll('[data-visited]').forEach(el=>el.onclick=()=>toggle('visited',el.dataset.visited));
if($('featureDate'))$('featureDate').onchange=e=>{if(e.target.value){focusDate=e.target.value;render()}};for(const k of ['favoritesOnly','racesOnly','spoiler'])if($(k))$(k).onchange=e=>{prefs[k]=e.target.checked;savePrefs();render()};if($('timezone'))$('timezone').onchange=e=>{prefs.timezone=e.target.value;savePrefs();render()};if($('reminder'))$('reminder').onchange=e=>{prefs.reminder=Number(e.target.value);savePrefs()};
if($('buildPlan'))$('buildPlan').onclick=()=>{planFrom=$('planFrom').value;planTo=$('planTo').value;if(planFrom>=planTo)return toast(t('invalid'));const [a,b]=weekendRange(focusDate);const timed=inRange(visibleRows(),a,b).filter(e=>!e.all_day&&e.status==='scheduled'&&startDay(e)===endDay(e)&&fmt(new Date(e.start_utc),{hour:'2-digit',minute:'2-digit',hourCycle:'h23'})>=planFrom&&fmt(new Date(e.end_utc),{hour:'2-digit',minute:'2-digit',hourCycle:'h23'})<=planTo).sort((a,b)=>Number(isFavorite(b))-Number(isFavorite(a))||a.start_utc.localeCompare(b.start_utc));let picked=[];for(const e of timed)if(!overlap([...picked,e]).length)picked.push(e);prefs.plan=picked.map(e=>e.id);savePrefs();render();toast(picked.length?x('planSaved'):x('noEvents'))};
if($('exportPlan'))$('exportPlan').onclick=()=>{if(!prefs.plan.length)return toast(x('noEvents'));location.href='/api/calendar.ics?ids='+prefs.plan.join(',')+'&alarm='+prefs.reminder};
if($('enableNotifications'))$('enableNotifications').onclick=async()=>{if(!('Notification'in window))return toast('Notifications are not supported in this browser.');prefs.notifications=await Notification.requestPermission()==='granted';savePrefs();toast(Notification.permission)};
if($('refreshData'))$('refreshData').onclick=()=>refreshData();if($('requestForm'))$('requestForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/requests',{name:e.target.elements.name.value});await fetchMeta();render()}catch(err){toast(err.message)}};document.querySelectorAll('[data-vote]').forEach(el=>el.onclick=async()=>{try{await api('/api/vote',{id:Number(el.dataset.vote),client});await fetchMeta();render()}catch(e){toast(e.message)}});
if($('scheduleImport'))$('scheduleImport').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>5000000)throw Error(t('invalid'));const data=JSON.parse(await f.text());if(!confirm('Import this schedule? Matching source IDs will be updated.'))return;const r=await api('/api/import',data);await refreshData();toast(JSON.stringify(r))}catch(err){toast(err.message)}};
document.querySelectorAll('[data-weather]').forEach(el=>el.onclick=async()=>{const e=events.find(r=>r.id===Number(el.dataset.weather)),target=$('weather-'+e.id);target.textContent='…';try{const w=await api('/api/weather?lat='+e.lat+'&lon='+e.lon);target.innerHTML=`<p>${x('forecastNote')}</p>`+link('https://open-meteo.com/','Open-Meteo')+'<div class="weather-grid">'+w.hourly.time.map((time,i)=>i%6===0?`<p>${esc(fmt(new Date(time+'Z'),{weekday:'short',hour:'2-digit'}))}<br>${w.hourly.temperature_2m[i]} °C · ${w.hourly.precipitation_probability[i]}% · ${w.hourly.wind_speed_10m[i]} km/h</p>`:'').join('')+'</div>'}catch(err){target.textContent=err.message}});}
async function fetchMeta(){const r=await Promise.allSettled([api('/api/status'),api('/api/requests')]);if(r[0].status==='fulfilled')statusData=r[0].value;if(r[1].status==='fulfilled')requests=r[1].value.requests}
async function refreshData(){try{const fresh=(await api('/api/events')).events;const changed=fresh.filter(e=>{const old=events.find(x=>x.id===e.id);return old&&(old.start_utc!==e.start_utc||old.status!==e.status)});events=fresh;storageOK=true;await fetchMeta();render();if(changed.length)toast('Schedule changed: '+changed.map(e=>e.series+' '+e.title).join(', '))}catch(e){toast(e.message)}}
const notified=new Set();setInterval(()=>{document.querySelectorAll('[data-countdown]').forEach(el=>{const e=events.find(x=>x.id===Number(el.dataset.countdown));if(e)el.textContent=countdown(e)});if(prefs.notifications&&'Notification'in window&&Notification.permission==='granted')for(const e of events){const delta=Date.parse(e.start_utc)-Date.now(),key=e.id+':'+e.start_utc;if(!e.all_day&&e.status==='scheduled'&&delta>0&&delta<=prefs.reminder*60000&&!notified.has(key)&&(!prefs.favoritesOnly||isFavorite(e))){notified.add(key);new Notification('GRIDLINE · '+e.series,{body:e.title+' · '+Math.ceil(delta/60000)+' min'})}}},30000);
setInterval(()=>{if(!dialog.open)refreshData()},300000);
document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{view=el.dataset.page;if(view==='settings')fetchMeta().then(render);render()});$('calendarMode').onchange=e=>{mode=e.target.value;render()};$('focusDate').value=focusDate;$('focusDate').onchange=e=>{if(e.target.value){focusDate=e.target.value;const d=new Date(focusDate+'T12:00:00');month=new Date(d.getFullYear(),d.getMonth(),1);render()}};
for(const [id,step]of [['prevMonth',-1],['nextMonth',1]])$(id).onclick=()=>{if(mode==='month')month=new Date(month.getFullYear(),month.getMonth()+step,1);else focusDate=plusDay(focusDate,step*(mode==='week'?7:1));$('focusDate').value=focusDate;render()};$('todayBtn').onclick=()=>{focusDate=dayInZone(new Date().toISOString());month=new Date(new Date().getFullYear(),new Date().getMonth(),1);$('focusDate').value=focusDate;render()};
$('exportBtn').onclick=()=>{location.href='/api/calendar.ics?alarm='+prefs.reminder+(filter!=='all'?'&series='+encodeURIComponent(filter):'')};$('seriesSelect').innerHTML=Object.keys(colors).map(s=>`<option>${esc(s)}</option>`).join('');$('sessionSelect').innerHTML=['weekend','practice','qualifying','sprint qualifying','sprint','hyperpole','race','stage','test'].map(s=>`<option>${s}</option>`).join('');view='home';fetchMeta();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});


initialize();
